package main

import (
	"flag"
	"os"
	"path/filepath"

	"github.com/septagon-oss/platformkit/kit/app"
	"github.com/septagon-oss/platformkit/kit/config"
	"github.com/septagon-oss/platformkit/pkit"
)

// compositionMarker is the first line of each COMPOSITION.<env>.md: the Go
// convention for a generated file, in Markdown's comment form.
const compositionMarker = "<!-- Code generated by platformkit composition; DO NOT EDIT. -->\n"

// writeComposition is `platformkit composition`: it writes COMPOSITION.<env>.md
// and .json for development and production into -dir, for the installation
// -config names. It opens nothing, so it runs offline; `make generate` is its caller.
func writeComposition(args []string) error {
	fs := flag.NewFlagSet("composition", flag.ContinueOnError)
	path := fs.String("config", "config.yaml", "Path to the configuration the documents describe")
	dir := fs.String("dir", ".", "Directory the four documents are written into")
	if err := fs.Parse(args); err != nil {
		return err
	}
	cfg, err := config.Load(*path)
	if err != nil {
		return err
	}
	for _, env := range []pkit.Environment{pkit.Development, pkit.Production} {
		md, js, err := compositionDocuments(cfg, env)
		if err != nil {
			return err
		}
		name := filepath.Join(*dir, "COMPOSITION."+string(env))
		if err := os.WriteFile(name+".md", md, 0o644); err != nil {
			return err
		}
		if err := os.WriteFile(name+".json", js, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// compositionDocuments is the text and the JSON composition document for one
// environment, as the composition command writes them and its tests compare them.
func compositionDocuments(cfg config.Config, env pkit.Environment) (md, js []byte, err error) {
	ref := composeReference(cfg, env)
	js, err = ref.describe()
	return []byte(compositionMarker + ref.explain(app.All)), js, err
}
